-- Initial migration, Phase 2 increment 13.
-- Authored from prisma/schema.prisma in this increment, because the
-- Prisma engine download fails in this workspace and no local Prisma
-- run can generate it. This file is NOT claimed as generated by a
-- local Prisma run. Its proof is the GitHub Actions workflow in
-- .github/workflows/prisma-migration.yml, which runs prisma migrate
-- deploy with this file against an ephemeral Postgres 15 service
-- container, and which also runs prisma migrate diff from empty to
-- the schema as a cross check artifact. Do NOT run this migration
-- against any real database. No live Neon database is connected in
-- this increment. The workflow for a real Neon database is
-- .github/workflows/neon-migrate-deploy.yml, manual only, and it
-- runs only after the owner adds a DATABASE_URL repo secret.
-- Tables: 32 models from the schema. Enums: 15. All ids are UUIDs
-- with gen_random_uuid defaults. All timestamps are TIMESTAMP(3).
-- No prices, trial values, or limits are hard coded here beyond
-- nullable configuration fields. Sample data: none.

CREATE TYPE "Role" AS ENUM ('user', 'admin');
CREATE TYPE "Edition" AS ENUM ('nvconsult', 'commercial');
CREATE TYPE "DocumentType" AS ENUM ('cv', 'coverLetter', 'motivationLetter', 'otherLetter', 'linkedinAbout', 'bio', 'personalStatement');
CREATE TYPE "PaperSize" AS ENUM ('A4', 'US_LETTER');
CREATE TYPE "DocumentStatus" AS ENUM ('draft', 'ready', 'archived');
CREATE TYPE "ExportFormat" AS ENUM ('pdf', 'docx', 'png', 'jpeg');
CREATE TYPE "ExportStatus" AS ENUM ('queued', 'processing', 'ready', 'failed');
CREATE TYPE "TemplateVersionStatus" AS ENUM ('draft', 'published', 'retired');
CREATE TYPE "CountryPackVersionStatus" AS ENUM ('draft', 'published', 'retired');
CREATE TYPE "ServiceType" AS ENUM ('freeReview', 'paidCreation');
CREATE TYPE "HumanReviewStatus" AS ENUM ('requested', 'inProgress', 'delivered', 'cancelled');
CREATE TYPE "TrialStatus" AS ENUM ('active', 'converted', 'expired', 'cancelled');
CREATE TYPE "ATSResult" AS ENUM ('pass', 'warning', 'fail');
CREATE TYPE "PlanScope" AS ENUM ('all', 'free', 'premium');
CREATE TYPE "ATSLevel" AS ENUM ('basic', 'advanced');

CREATE TABLE "User" (
    "id" TEXT NOT NULL DEFAULT gen_random_uuid(),
    "email" TEXT NOT NULL,
    "name" TEXT,
    "passwordHash" TEXT NOT NULL,
    "role" "Role" NOT NULL DEFAULT 'user',
    "edition" "Edition" NOT NULL DEFAULT 'commercial',
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    "deletedAt" TIMESTAMP(3),
    CONSTRAINT "User_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE INDEX "User_email_idx" ON "User"("email");
CREATE INDEX "User_edition_idx" ON "User"("edition");

CREATE TABLE "Profile" (
